from rest_framework.views import APIView
from rest_framework.response import Response
from .models import Owner, Gym
from .serializers import OwnerSerializer

class OwnerUpdateView(APIView):
    def put(self, request, pk):
        if request.user.is_superuser:
            # Superusers can update any owner
            try:
                owner = Owner.objects.get(userCustom=pk)
            except Owner.DoesNotExist:
                return Response('Owner not found', status=404)
        elif request.user.rol == 'owner' and request.user.username == pk:
            # Owners can update their own data
            try:
                owner = Owner.objects.get(userCustom=pk)
            except Owner.DoesNotExist:
                return Response('Owner not found', status=404)
        elif request.user.rol == 'gym':
            # Gyms can update owners associated with them
            try:
                gym = Gym.objects.get(userCustom=request.user)
                owner = Owner.objects.get(userCustom=pk)
                if gym.owner != owner:
                    return Response('You are not authorized to update this owner', status=403)
            except Gym.DoesNotExist:
                return Response('Gym not found', status=404)
            except Owner.DoesNotExist:
                return Response('Owner not found', status=404)
        else:
            return Response('You are not authorized to update an owner', status=403)

        # Now update the owner with the provided data
        serializer = OwnerSerializer(owner, data=request.data, partial=True)
        if serializer.is_valid():
            serializer.save()
            return Response(serializer.data)
        return Response(serializer.errors, status=400)

