// Function to read and parse the observablehq.config.ts file
function parseConfigFile() {
    const configFile = fs.readFileSync('observablehq.config.ts', 'utf-8');
    const footerLine = configFile.match(/footer:\s*['"]([^'"]+)['"]/);
    if (footerLine && footerLine.length > 1) {
        const footerContent = footerLine[1];
        if (footerContent.includes('<a id="changed">')) {
            return true;
        }
    }
    return false;
}

// Function to cache the content of index.html pages from the dist folder
function cacheIndexPages() {
    const distFiles = fs.readdirSync('dist');
    const indexFiles = distFiles.filter(file => file.endsWith('.html'));

    const cachedIndexPages = {};
    indexFiles.forEach(file => {
        const content = fs.readFileSync(`dist/${file}`, 'utf-8');
        cachedIndexPages[file] = content;
    });

    return cachedIndexPages;
}

// Function to compare cached index pages with the new ones
function compareIndexPages(cachedPages) {
    const distFiles = fs.readdirSync('dist');
    const indexFiles = distFiles.filter(file => file.endsWith('.html'));

    indexFiles.forEach(file => {
        const content = fs.readFileSync(`dist/${file}`, 'utf-8');
        if (cachedPages[file] !== content) {
            updateChangeHistory(file);
        }
    });
}

// Function to update the change history
function updateChangeHistory(file) {
    const content = fs.readFileSync(`dist/${file}`, 'utf-8');
    const $ = cheerio.load(content);

    // Parse existing change history
    let changeHistory = $('a#changed').attr('title') || '';
    changeHistory = changeHistory.split(', ');

    // Prepend the most recent change
    const currentDate = new Date().toISOString();
    changeHistory.unshift(`Changed ${currentDate}`);

    // Truncate if necessary
    if (changeHistory.join(', ').length > 2500) {
        changeHistory.pop();
    }

    // Update change history in the footer
    $('a#changed').attr('title', changeHistory.join(', '));

    // Insert JavaScript for change history interaction if not already present
    if (!$('script#change-history-script').length) {
        $('body').append(`
            <script id="change-history-script">
                // JavaScript code for change history interaction
                // Implement toggling visibility, sorting, etc.
            </script>
        `);
    }

    // Save the updated content
    fs.writeFileSync(`dist/${file}`, $.html());
}

// Main function
function main() {
    if (!parseConfigFile()) {
        console.log('No "changed" element found in the footer.');
        return;
    }

    const cachedIndexPages = cacheIndexPages();
    compareIndexPages(cachedIndexPages);

    console.log('Change history updated successfully.');
}

// Run the main function
main();

