#include "spdlog/sinks/base_sink.h"
#include "spdlog/details/null_mutex.h"
#include <mutex>

namespace HelloImGui {
    // Your HelloImGui namespace details here
}

template<typename Mutex>
class hello_imgui_sink : public spdlog::sinks::base_sink<Mutex>
{
protected:
    void sink_it_(const spdlog::details::log_msg& msg) override
    {
        spdlog::memory_buf_t formatted;
        spdlog::sinks::base_sink<Mutex>::formatter_->format(msg, formatted);
        std::string message = fmt::to_string(formatted);

        switch (msg.level) {
            case spdlog::level::debug:
                HelloImGui::Log(HelloImGui::LogLevel::Debug, "%s", message.c_str());
                break;
            case spdlog::level::info:
                HelloImGui::Log(HelloImGui::LogLevel::Info, "%s", message.c_str());
                break;
            case spdlog::level::warn:
                HelloImGui::Log(HelloImGui::LogLevel::Warning, "%s", message.c_str());
                break;
            case spdlog::level::err:
                HelloImGui::Log(HelloImGui::LogLevel::Error, "%s", message.c_str());
                break;
            default:
                HelloImGui::Log(HelloImGui::LogLevel::Info, "%s", message.c_str());
                break;
        }
    }

