grammar ArithmeticExpr;

// Parser rules
expr:   term ((PLUS | MINUS) term)*;
term:   factor ((TIMES | DIV) factor)*;
factor: NUMBER | VARIABLE | LPAREN expr RPAREN;

// Lexer rules
PLUS:   '+';
MINUS:  '-';
TIMES:  '*';
DIV:    '/';
LPAREN: '(';
RPAREN: ')';
NUMBER: [0-9]+ ('.' [0-9]+)?;
VARIABLE: [a-zA-Z]+;

WS:     [ \t\r\n]+ -> skip;

using Antlr4.Runtime;
using System;

class Program
{
    static void Main(string[] args)
    {
        string expression = "2 * (3 + x)";
        var inputStream = new AntlrInputStream(expression);
        var lexer = new ArithmeticExprLexer(inputStream);
        var tokens = new CommonTokenStream(lexer);
        var parser = new ArithmeticExprParser(tokens);

        var visitor = new ArithmeticExprVisitor();
        var result = visitor.Visit(parser.expr());

        Console.WriteLine($"Result: {result}");
    }
}

public class ArithmeticExprVisitor : ArithmeticExprBaseVisitor<double>
{
    public override double VisitExpr(ArithmeticExprParser.ExprContext context)
    {
        return Visit(context.term(0));
    }

    public override double VisitTerm(ArithmeticExprParser.TermContext context)
    {
        double result = Visit(context.factor(0));
        for (int i = 1; i < context.factor().Length; i++)
        {
            if (context.GetChild(i * 2 - 1).GetText() == "*")
                result *= Visit(context.GetChild(i * 2));
            else
                result /= Visit(context.GetChild(i * 2));
        }
        return result;
    }

    public override double VisitFactor(ArithmeticExprParser.FactorContext context)
    {
        if (context.NUMBER() != null)
            return double.Parse(context.NUMBER().GetText());
        else if (context.VARIABLE() != null)
        {
            // Here you would fetch the value of the variable from your context/environment
            // For simplicity, let's assume it's 5 for any variable
            return 5; 
        }
        else
            return Visit(context.expr());
    }
}

