import Feature from 'ol/Feature';
import Geometry from 'ol/geom/Geometry';
import Collection from 'ol/Collection';

interface Entity {
    id: string;
    geometry?: Geometry;
    attributes?: { [key: string]: any };
}

function updateFeatureCollection(features: Collection<Feature>, entities: Entity[]): void {
    const featureMap = new Map<string, Feature>();

    // Map existing features by their ID for quick lookup
    features.forEach(feature => {
        const id = feature.getId() as string;
        featureMap.set(id, feature);
    });

    // Process each entity
    entities.forEach(entity => {
        const { id, geometry, attributes } = entity;
        if (featureMap.has(id)) {
            const feature = featureMap.get(id)!;

            // Update geometry if it exists
            if (geometry) {
                feature.setGeometry(geometry);
            }

            // Update attributes if they exist
            if (attributes) {
                feature.setProperties(attributes);
            }

            // Remove from map to mark as updated
            featureMap.delete(id);
        } else {
            // Create new feature if not exist
            const newFeature = new Feature({
                ...attributes,
                geometry: geometry
            });
            newFeature.setId(id);
            features.push(newFeature);
        }
    });

    // Remove features not present in the new entity list
    featureMap.forEach((feature, id) => {
        features.remove(feature);
    });
}

