  // 分段处理
  const MAX_LENGTH = 1000; // 假设每段最大长度为1000字符
  const segments = [];
  let currentSegment = '';
  content.split('\n').forEach(line => {
    if (currentSegment.length + line.length > MAX_LENGTH) {
      segments.push(currentSegment);
      currentSegment = line;
    } else {
      currentSegment += line + '\n';
    }
  });
  if (currentSegment.length > 0) {
    segments.push(currentSegment);
  }

  return segments.map(segment => ({ ...article, content: segment }));
};

